    const headers = createGitHubHeaders(token);
    const refUrl = `${GITHUB_API_BASE}/repos/${owner}/${repo}/git/ref/heads/${encodeURIComponent(branch)}`;
    const refResponse = await fetch(refUrl, { headers });

